'use strict';
/* Journey: SO(3) — the non-commutative case. The Geometry planet's fourth moon.

   Five stations, chosen so that nothing here re-derives what `so3-optimization` already
   owns (see D4 in docs/project/design-decisions.md). That journey covers the constraint
   RᵀR = I as an obstacle to optimization, exp as compound interest, and the true shape of
   SO(3) — in particular the π₁ = ℤ/2 ball is ITS station 6, so this moon states the
   invariant and never draws that ball. None of it covers Euler's theorem, the failure of
   commutativity, or gimbal lock — which is exactly what this moon takes:

     1 · every rotation has an axis (Euler), so R = R(a, θ) and the tangent vector is ω = aθ
     2 · R_x R_z ≠ R_z R_x, worked on one basis vector, and why body/world descends from it
     3 · gimbal lock OBSERVED — a degree of freedom dies, the map loses rank, and the reason
         is that yaw+pitch are the longitude/latitude of the inner axis: the lock is the
         pole of that chart. Names `chart`; asks whether one can ever suffice.
     4 · the answer on the smallest curved space, S¹ ≅ SO(2): one chart leaves a seam that
         slides but never closes, two overlapping ones (an atlas) do cover it. This is
         where `why flat at all`, Sⁿ, open, compactness, atlas and π₁ are introduced —
         the level where each is simplest but its point is already visible.
     5 · the theorem and its price. S² is the middle rung (π₁ = 0 yet still not one chart,
         so compactness is the obstruction that works alone), then SO(3): the invariants,
         what each 3-parameter scheme pays with (Euler: rank; Rodrigues: a seam at θ = π),
         and why the quaternion's S³ — one more rung of the SAME ladder — is smooth but
         still not flat. Ends on storage vs. increment.

   Stations 3–5 all show the same collapse computed rather than drawn: the roll axis
   projected on the yaw axis is exactly sin β (3); the marker's own θ jumps +π → −π across
   the chart gap (4); the arc between two markers a fixed Δλ apart is R·Δλ·cos φ, which
   dies at the pole (5). The concept ladder S¹ → S² → S³ is why station 5 can name the
   quaternion's sphere without introducing it from nowhere — do not reorder them.
   Backing notes: docs/geometry/so3.md, docs/geometry/topology-obstruction.md,
   docs/geometry/topological-vocabulary.md.
   Cards (hu/en/ja) in-file. Requires LIE.kit. */
window.LIE = window.LIE || {};
LIE.journeys = LIE.journeys || {};
LIE.journeys['geometry-so3'] = (function(){
  const K = LIE.kit;
  const { V3, ease, clamp, hexStr, fatArrow, setArrow, makeLabel, updateLabel,
          baseSphere } = K;

  const SP  = [V3(0,0,0), V3(44,5,-12), V3(88,-4,10), V3(132,6,-6), V3(176,-5,12)];
  const OFF = [V3(0,2.6,9.0), V3(1.1,2.9,10.4), V3(0,2.6,9.6),
               V3(0,1.0,10.2), V3(0.5,2.2,9.2)];

  const AXIS = V3(0.55, 0.78, 0.30).normalize();     // the invariant axis at station 1
  const HALF = Math.PI/2;

  function build(C, PAL){
    const COL = PAL || K.palette('dark');
    const HX = { teal:hexStr(COL.teal), coral:hexStr(COL.coral), violet:hexStr(COL.violet),
                 amber:hexStr(COL.amber), green:hexStr(COL.green), ink:hexStr(COL.ink) };

    function line(g, pts, color, op){
      const l = new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts),
        new THREE.LineBasicMaterial({color, transparent:true, opacity:op===undefined?0.9:op}));
      g.add(l); return l;
    }
    function dot(g, color, r){
      const d = new THREE.Mesh(new THREE.SphereGeometry(r||0.1,14,12), new THREE.MeshBasicMaterial({color}));
      g.add(d); return d;
    }
    function dimArrow(g, color, r, from, to, op){
      const a = fatArrow(color, r); setArrow(a, from, to);
      a.userData.cyl.material.transparent = true; a.userData.cyl.material.opacity = op;
      a.userData.cone.material.transparent = true; a.userData.cone.material.opacity = op;
      g.add(a); return a;
    }
    // a body whose orientation is readable from any angle: a coral/teal/violet triad
    function triad(g, L, r){
      const t = new THREE.Group();
      [[V3(L,0,0),COL.coral],[V3(0,L,0),COL.teal],[V3(0,0,L),COL.violet]].forEach(([v,c])=>{
        const a = fatArrow(c, r||0.05); setArrow(a, V3(0,0,0), v); t.add(a);
      });
      g.add(t); return t;
    }
    // the circle a point sweeps when the body turns about `ax`
    function orbitPts(p, ax, seg){
      const out = [];
      for(let i=0;i<=seg;i++) out.push(p.clone().applyAxisAngle(ax, i/seg*Math.PI*2));
      return out;
    }
    // a circle of radius r in the plane spanned by the two given unit vectors
    function ringPts(r, u, v, seg){
      const out = [];
      for(let i=0;i<=seg;i++){ const a = i/seg*Math.PI*2;
        out.push(u.clone().multiplyScalar(Math.cos(a)*r).add(v.clone().multiplyScalar(Math.sin(a)*r))); }
      return out;
    }
    // an arc of the same circle, from a0 to a1 — the ring minus the bit a chart misses
    function arcPts(r, u, v, a0, a1, seg){
      const out = [];
      for(let i=0;i<=seg;i++){ const a = a0 + (a1-a0)*i/seg;
        out.push(u.clone().multiplyScalar(Math.cos(a)*r).add(v.clone().multiplyScalar(Math.sin(a)*r))); }
      return out;
    }
    function wireBubble(infoId, popId){
      const info=document.getElementById(infoId), pop=document.getElementById(popId);
      if(!info || !pop) return;
      info.onclick=e=>{
        e.stopPropagation();
        const willOpen = pop.hidden;
        document.querySelectorAll('.bubble:not([hidden]), .pop:not([hidden])').forEach(o=>{
          if(o!==pop){ o.hidden=true; const t=document.querySelector('[aria-controls="'+o.id+'"]'); if(t) t.setAttribute('aria-expanded','false'); }
        });
        pop.hidden=!willOpen; info.setAttribute('aria-expanded', willOpen?'true':'false');
      };
    }

    const stations = [
      /* 0 · Euler's theorem, made visible: one line stays put while everything else sweeps
            a circle around it. The orbits are drawn for two corners of the body, so the
            axis reads as "the only place where nothing happens". */
      g=>{
        const A = AXIS;
        line(g, [A.clone().multiplyScalar(-2.9), A.clone().multiplyScalar(2.9)], COL.green, 0.45);
        dimArrow(g, COL.green, 0.045, V3(0,0,0), A.clone().multiplyScalar(2.5), 0.95);
        const fixed = dot(g, COL.green, 0.1); fixed.position.copy(A.clone().multiplyScalar(1.35));

        const body = triad(g, 1.7, 0.05);
        const box = new THREE.Mesh(new THREE.BoxGeometry(1.15,1.15,1.15),
          new THREE.MeshBasicMaterial({color:COL.teal, wireframe:true, transparent:true, opacity:0.30}));
        body.add(box);

        // two body points and the circles they will travel
        const marks = [V3(1.7,0,0), V3(0,0,1.7)];
        marks.forEach(p=>line(g, orbitPts(p, A, 72), COL.amber, 0.30));
        const riders = marks.map(()=>dot(g, COL.amber, 0.085));

        const lbl = makeLabel('R = R(a, θ)', HX.green, 3.0); lbl.position.set(0, 3.15, 0); g.add(lbl);
        return {tick(t){
          const th = t*0.42;
          body.quaternion.setFromAxisAngle(A, th);
          marks.forEach((p,i)=>riders[i].position.copy(p.clone().applyAxisAngle(A, th)));
        }};
      },

      /* 1 · the same two right angles in both orders. Left: about world z, then world y.
            Right: y, then z. Each new rotation is composed on the LEFT, because both are
            rotations about the world's axes.
            The axis pair is chosen for legibility: following the violet z-arm, one order
            lands it on +x and the other on +y — both in the screen plane. Rotating about
            x and z instead would send one result straight at the camera, where a 90°
            difference reads as a dot. */
      g=>{
        const qz = new THREE.Quaternion(), qy = new THREE.Quaternion();
        const mk = (x, txt, hx)=>{
          const holder = new THREE.Group(); holder.position.set(x, 0, 0); g.add(holder);
          const t = triad(holder, 1.55, 0.052);
          t.add(new THREE.Mesh(new THREE.BoxGeometry(1.0,1.0,1.0),
            new THREE.MeshBasicMaterial({color:COL.teal, wireframe:true, transparent:true, opacity:0.22})));
          const l = makeLabel(txt, hx, 2.9); l.position.set(x, -2.35, 0); g.add(l);
          return t;
        };
        const bodyA = mk(-2.6, 'R(y) R(z)', HX.amber);     // z applied first
        const bodyB = mk( 2.6, 'R(z) R(y)', HX.violet);    // y applied first
        // the world frame both are measured against
        dimArrow(g, COL.coral, 0.02, V3(0,-0.2,0), V3(1.0,-0.2,0), 0.22);
        dimArrow(g, COL.teal,  0.02, V3(0,-0.2,0), V3(0,0.8,0), 0.22);

        const T0=0.9, T1=1.5, T2=0.6, T3=1.5, T4=1.8, PER=T0+T1+T2+T3+T4;
        return {tick(t){
          const tc = t % PER;
          let a=0, b=0;
          if(tc < T0){ a=0; b=0; }
          else if(tc < T0+T1){ a = HALF*ease((tc-T0)/T1); b = 0; }
          else if(tc < T0+T1+T2){ a = HALF; b = 0; }
          else if(tc < T0+T1+T2+T3){ a = HALF; b = HALF*ease((tc-T0-T1-T2)/T3); }
          else { a = HALF; b = HALF; }
          // A: first about z (angle a), then about y (angle b) → q = qy(b) · qz(a)
          qz.setFromAxisAngle(V3(0,0,1), a); qy.setFromAxisAngle(V3(0,1,0), b);
          bodyA.quaternion.copy(qy).multiply(qz);
          // B: first about y (angle a), then about z (angle b) → q = qz(b) · qy(a)
          qy.setFromAxisAngle(V3(0,1,0), a); qz.setFromAxisAngle(V3(0,0,1), b);
          bodyB.quaternion.copy(qz).multiply(qy);
        }};
      },

      /* 2 · gimbal lock. Three nested rings; the roll axis in world coordinates is
            (cos β sin α, −sin β, cos β cos α), so its overlap with the yaw axis is exactly
            |sin β| — the coral warning arrow is driven by that number, not by a timer. */
      g=>{
        const ex = V3(1,0,0), ey = V3(0,1,0), ez = V3(0,0,1);
        const Gy = new THREE.Group(); g.add(Gy);                       // yaw, about world y
        line(Gy, ringPts(2.45, ex, ez, 80), COL.teal, 0.5);
        const Gp = new THREE.Group(); Gy.add(Gp);                      // pitch, about local x
        line(Gp, ringPts(1.90, ey, ez, 80), COL.violet, 0.5);
        const Gr = new THREE.Group(); Gp.add(Gr);                      // roll, about local z
        line(Gr, ringPts(1.38, ex, ey, 80), COL.amber, 0.5);
        triad(Gr, 1.0, 0.045);

        dimArrow(Gy, COL.teal,   0.03, V3(0,-2.7,0), V3(0,5.4,0), 0.55);   // yaw axis
        dimArrow(Gp, COL.violet, 0.03, V3(-2.1,0,0), V3(4.2,0,0), 0.45);   // pitch axis
        dimArrow(Gr, COL.amber,  0.03, V3(0,0,-1.6), V3(0,0,3.2), 0.45);   // roll axis
        const warn = dimArrow(g, COL.coral, 0.055, V3(0,-2.9,0), V3(0,5.8,0), 0.0);
        const lbl = makeLabel('β → 90°', HX.coral, 2.6); lbl.position.set(0, 3.25, 0);
        lbl.material.opacity = 0; g.add(lbl);

        return {tick(t){
          const beta = HALF * 0.5 * (1 - Math.cos(t*0.55));      // 0 … 90° … 0
          Gy.rotation.y = t*0.23;
          Gp.rotation.x = beta;
          Gr.rotation.z = t*0.37;
          // |roll axis · yaw axis| = |sin β| — one when the two dials turn the same way
          const overlap = Math.abs(Math.sin(beta));
          const w = clamp((overlap - 0.90)/0.09, 0, 1);
          warn.userData.cyl.material.opacity = w*0.75;
          warn.userData.cone.material.opacity = w*0.75;
          lbl.material.opacity = w;
        }};
      },
      /* 3 · the smallest curved space there is: S¹ ≅ SO(2). The amber arc is one chart,
            θ ∈ (−π, π), and the gap in it is the single point that chart cannot name.
            The green marker carries its own live θ, so the jump from +π to −π as it
            crosses the gap is read off the label rather than asserted. On the second
            lap a teal second chart fades in over the gap: the smallest atlas of the
            circle, two charts with overlap on both sides. */
      g=>{
        const R = 2.25, GAP = 0.30, ex = V3(1,0,0), ey = V3(0,1,0);
        line(g, ringPts(R, ex, ey, 140), COL.ink, 0.22);
        line(g, arcPts(R, ex, ey, -Math.PI+GAP, Math.PI-GAP, 130), COL.amber, 0.90);
        const seam = dot(g, COL.coral, 0.115); seam.position.set(-R, 0, 0);
        // the second chart, drawn slightly outside the ring so the overlap is visible
        const c2 = line(g, arcPts(R*1.10, ex, ey, Math.PI-0.80, Math.PI+0.80, 60), COL.teal, 0.0);

        const mark = dot(g, COL.green, 0.13);
        const lbl = makeLabel('θ = +0.0', HX.green, 2.2); g.add(lbl);
        const s1 = makeLabel('S^{1}', HX.ink, 1.4); s1.position.set(0, 0.1, 0); g.add(s1);
        const PER = 4*Math.PI/0.55;                    // two laps of the marker
        let last = 'θ = +0.0';
        return {tick(t){
          const a = (t*0.55) % (Math.PI*2);            // 0 … 2π round the ring
          const th = a > Math.PI ? a - Math.PI*2 : a;  // the same point in the chart, (−π, π]
          mark.position.set(R*Math.cos(a), R*Math.sin(a), 0);
          lbl.position.set(R*1.58*Math.cos(a), R*1.58*Math.sin(a), 0);
          // one decimal, and only on change: updateLabel rebuilds a canvas texture
          const txt = 'θ = ' + (th<0?'−':'+') + Math.abs(th).toFixed(1);
          if(txt!==last){ updateLabel(lbl, txt, HX.green); last=txt; }
          c2.material.opacity = clamp(((t % PER)/PER - 0.5)*6, 0, 1) * 0.85;
        }};
      },

      /* 4 · the same failure one rung up. The meridians converge at the poles, so two
            markers held a fixed Δλ apart in longitude sit R·Δλ·cos φ apart on the
            surface — the amber arc between them is drawn from those two positions, so
            its collapse at the pole is computed, exactly as |sin β| was on the rings. */
      g=>{
        const R = 2.05, DLON = 0.95, SEG = 14;
        const ex = V3(1,0,0), ey = V3(0,1,0), ez = V3(0,0,1);
        const S = new THREE.Group(); g.add(S);
        S.add(baseSphere(R*0.985, COL));
        for(let k=0;k<8;k++){                                  // meridians
          const l = k/8*Math.PI;
          line(S, ringPts(R, V3(Math.cos(l),0,Math.sin(l)), ey, 90), COL.teal, 0.30);
        }
        [-60,-30,0,30,60].forEach(d=>{                         // parallels
          const p = d*Math.PI/180, pts = ringPts(R*Math.cos(p), ex, ez, 80);
          pts.forEach(q=>q.y = R*Math.sin(p));
          line(S, pts, COL.teal, d===0 ? 0.42 : 0.20);
        });
        [1,-1].forEach(sgn=>{ const p = dot(S, COL.coral, 0.10); p.position.set(0, sgn*R, 0); });

        const at = (phi,lam)=>V3(R*Math.cos(phi)*Math.cos(lam), R*Math.sin(phi),
                                 R*Math.cos(phi)*Math.sin(lam));
        const m1 = dot(S, COL.amber, 0.115), m2 = dot(S, COL.amber, 0.115);
        // the arc between the two markers: SEG+1 points, rewritten every tick
        const seed = []; for(let i=0;i<=SEG;i++) seed.push(at(0, 0.6 + DLON*i/SEG));
        const span = line(S, seed, COL.amber, 0.95);
        const pos = span.geometry.attributes.position;

        const s2 = makeLabel('S^{2}', HX.ink, 1.4); s2.position.set(0, -R-0.85, 0); g.add(s2);
        const warn = makeLabel('φ → 90°', HX.coral, 2.5); warn.position.set(0, R+0.95, 0);
        warn.material.opacity = 0; g.add(warn);
        return {tick(t){
          S.rotation.y = t*0.16;
          const phi = (Math.PI/2)*0.5*(1 - Math.cos(t*0.5));   // 0 … 90° … 0
          const lam = 0.6;
          for(let i=0;i<=SEG;i++){
            const p = at(phi, lam + DLON*i/SEG);
            pos.setXYZ(i, p.x, p.y, p.z);
          }
          pos.needsUpdate = true;
          m1.position.copy(at(phi, lam)); m2.position.copy(at(phi, lam+DLON));
          // what dies at the pole is cos φ — the whole span shrinks with it
          warn.material.opacity = clamp((0.22 - Math.cos(phi))/0.18, 0, 1);
        }};
      }
    ];

    function bindCard(i){
      wireBubble('so3gEulerInfo','so3gEulerNote');   // card 1 · why 1 is always an eigenvalue
      wireBubble('so3gHatInfo','so3gHatNote');       // card 1 · why the hat is skew-symmetric
      wireBubble('so3gCommInfo','so3gCommNote');     // card 2 · BCH, and why small angles hide it
      wireBubble('so3gDroneInfo','so3gDroneNote');   // card 2 · the pull-back, and Ad_R = R
      wireBubble('so3gCircInfo','so3gCircNote');     // card 4 · compactness, precisely
      wireBubble('so3gTopInfo','so3gTopNote');       // card 5 · the precise definitions
    }

    return { stations, bindCard };
  }

  return {
    id: 'geometry-so3',
    tier: 'geometry',
    layout: { SP, OFF },
    threadKey: 'teal',
    // Curriculum position, as data rather than prose: `next` is the following moon in
    // hub.js's BRANCHES order (crossing into the next branch at a branch end), `handoffs`
    // are the topical pointers this journey's cards name, `requires` the hard
    // back-references its opening card makes. engine.js renders next+handoffs as links
    // on the last station; check.html verifies every id resolves and that the next-chain
    // still agrees with BRANCHES.
    seq: { next: 'geometry-se3', requires: ['geometry-so2'], handoffs: ['so3-optimization'] },
    build,
    cards: {
      hu: [
        {t:'Minden forgatásnak van tengelye', b:'<p>Mit csinál egy <span class="m">R ∈ SO(3)</span> <em>valójában</em>? A válasz Euler tétele, és meglepően erős: <strong>minden</strong> forgatásnak van egy tengelye — egy egyenes, amit helyben hagy.</p><p>Nem „a legtöbbnek”, nem „a szépeknek”. Mindegyiknek, és a <button class="termbtn" id="so3gEulerInfo" type="button" aria-expanded="false" aria-controls="so3gEulerNote">bizonyítás három sor</button>.</p><p>A jelenetben ez látszik: a zöld egyenes áll, minden más pont kört ír le körülötte. Ezért írható minden forgatás így:</p><p class="matline"><span class="m">R = R(a, θ)</span></p><p class="matline"><span class="m">‖a‖ = 1</span></p><p>Egy <span class="m">a</span> egységvektor és egy <span class="m">θ</span> szög. Számoljuk meg a szabadsági fokokat innen: az <span class="m">a</span> az egységgömb egy pontja, az <strong>2</strong>; a <span class="m">θ</span> egy szám, az <strong>1</strong>. Összesen <strong>3</strong> — ugyanaz a három, ami a <span class="m">R<sup>⊤</sup>R = I</span> kényszerből is kijön, csak egészen más úton.</p><p>És most a lényeg, amiért ez itt van: a tengely és a szög összeszorozható <em>egyetlen</em> vektorrá.</p><p class="matline"><span class="m">ω = a θ ∈ ℝ<sup>3</sup></span></p><p>Ez már egy közönséges 3-vektor: összeadható, skálázható, deriválható. Ez lesz az az érintőtér-vektor, amit az <span class="m">exp</span> visszavisz a csoportba. A tér, ahol a <span class="m">ω</span> él, lapos; a tér, ahol az <span class="m">R</span> él, nem — és a kettő közti oda-vissza az egész gépezet.</p><p>Egy bökkenő: az <span class="m">exp</span> nem vektort vár. A sora — <span class="m">I + X + ½X<sup>2</sup> + …</span> — olyan <span class="m">X</span>-et kíván, ami önmagával szorozható, az <span class="m">ω</span> viszont három szám oszlopa. A <button class="termbtn" id="so3gHatInfo" type="button" aria-expanded="false" aria-controls="so3gHatNote">kalap</button> hidalja át ezt: a három számot abba a mátrixba rendezi, amelyik a vektoriális szorzatot adja vissza.</p><p class="matline"><span class="m">ω<sup>∧</sup> =</span><span class="matrix"><span class="mbracket"></span><span class="mgrid"><span>0</span><span>&minus;ω<sub>3</sub></span><span>ω<sub>2</sub></span><span>ω<sub>3</sub></span><span>0</span><span>&minus;ω<sub>1</sub></span><span>&minus;ω<sub>2</sub></span><span>ω<sub>1</sub></span><span>0</span></span><span class="mbracket right"></span></span></p><p class="matline"><span class="m">ω<sup>∧</sup> v = ω × v</span></p><p>Így már az <span class="m">R = exp(ω<sup>∧</sup>)</span> is értelmes, és az a lapos tér, amit ezek a mátrixok alkotnak — összeadásra és skálázásra zárt, ellentétben magával az <span class="m">SO(3)</span>-mal —, a <span class="m">so(3)</span> Lie-algebra. A kalap lineáris, tehát <span class="m">ω<sup>∧</sup> = (aθ)<sup>∧</sup> = θ a<sup>∧</sup></span>: az <span class="m">exp(â θ)</span>, amit az <span class="m">SO(2)</span> hold a három kódolás táblázatába írt, pontosan ez a kifejezés — az <span class="m">SE(3)</span> pedig változatlanul újrahasználja az operátort, a 4×4-esének forgatás-blokkjaként.</p><div class="bubble" id="so3gHatNote" role="dialog" aria-label="Miert ferden szimmetrikus" hidden><p>A ferde szimmetria <strong>kényszer</strong>, nem választás. Deriváljuk az <span class="m">R<sup>⊤</sup>R = I</span> megkötést egy mozgás mentén:</p><p class="matline"><span class="m">Ṙ<sup>⊤</sup>R + R<sup>⊤</sup>Ṙ = 0 ⟹ (R<sup>⊤</sup>Ṙ)<sup>⊤</sup> = −R<sup>⊤</sup>Ṙ</span></p><p>Tehát minden megengedett sebesség — az egységelemnél felírva — ferdén szimmetrikus mátrix. Számoljuk meg a szabad elemeit: az átló nulla, az alsó háromszög a felsőnek a mínusza, marad <strong>3</strong>. Ugyanaz a 3, mint a tengely-és-szög számolásból fent, és ugyanaz, amit a megkötés hagyott — harmadik út ugyanahhoz a számhoz.</p><p>Az inverz leképezés a mátrixot viszi vissza vektorrá, jele <span class="m">∨</span>:</p><p class="matline"><span class="m">(ω<sup>∧</sup>)<sup>∨</sup> = ω</span></p></div><div class="bubble" id="so3gEulerNote" role="dialog" aria-label="Euler tetelenek bizonyitasa" hidden><p>Azt kell megmutatni, hogy <span class="m">1</span> sajátértéke <span class="m">R</span>-nek, azaz <span class="m">det(R − I) = 0</span>. Használjuk, hogy <span class="m">R R<sup>⊤</sup> = I</span> és <span class="m">det R = 1</span>:</p><p class="matline"><span class="m">det(R − I) = det(R − R R<sup>⊤</sup>) = det R · det(I − R<sup>⊤</sup>)</span></p><p class="matline"><span class="m">= det((I − R)<sup>⊤</sup>) = det(I − R) = (−1)<sup>3</sup> det(R − I)</span></p><p>Tehát <span class="m">det(R − I) = −det(R − I)</span>, vagyis <span class="m">det(R − I) = 0</span>. Van olyan nemnulla <span class="m">a</span>, amire <span class="m">R a = a</span>: ez a tengely.</p><p>Figyeld meg, hol dolgozik a <strong>páratlan</strong> dimenzió: a <span class="m">(−1)<sup>3</sup></span> tényezőben. Páros dimenzióban a bizonyítás elromlik, és jogosan — egy síkbeli forgatásnak (<span class="m">SO(2)</span>) <em>nincs</em> fix iránya, csak fix pontja.</p></div>'},
        {t:'A sorrend számít, 3D-ben', b:'<p><span class="m">SO(2)</span> kommutatív volt. <span class="m">SE(2)</span> már nem — de ott a nem-kommutativitás az eltolásból jött, a forgatásrész továbbra is jól viselkedett. Itt maga a forgatás romlik el.</p><p>Vegyünk két derékszöget: forgatás a világ <span class="m">z</span> tengelye körül, és forgatás a világ <span class="m">y</span> tengelye körül. Kövessük a lila <span class="m">e<sub>z</sub></span> irányt.</p><p class="matline"><span class="m">előbb z, aztán y:&nbsp; e<sub>z</sub> → e<sub>z</sub> → e<sub>x</sub></span></p><p class="matline"><span class="m">előbb y, aztán z:&nbsp; e<sub>z</sub> → e<sub>x</sub> → e<sub>y</sub></span></p><p>Ugyanaz a két mozdulat, és a lila tengely az egyik esetben <span class="m">x</span>-re, a másikban <span class="m">y</span>-ra mutat. Nem finom eltérés: <strong>90°</strong>.</p><p class="matline"><span class="m">R<sub>y</sub> R<sub>z</sub> ≠ R<sub>z</sub> R<sub>y</sub></span></p><p>Ez a <em>theory-map</em> szerinti „egy új dolog” <span class="m">SO(3)</span>-ban, és sokkal messzebbre gyűrűzik, mint elsőre látszik. Ha a szorzás sorrendje számít, akkor számít az is, hogy egy <span class="m">δ</span> perturbációt <strong>balról vagy jobbról</strong> szorzunk rá a becslésre:</p><p class="matline"><span class="m">exp(δ) R</span>&nbsp;&nbsp;vagy&nbsp;&nbsp;<span class="m">R exp(δ)</span></p><p>Az első a világ koordinátáiban perturbál, a második a testében. Ez a <em>body vs. world</em> distinkció, és a teljes tartalma ez az egy egyenlőtlenség. Hogy melyiket hívjuk „body”-nak, az <em>konvenció</em>; hogy a kettő <em>különbözik</em>, az <em>tétel</em>.</p><p>És ugyanez <em>mozgás közben</em>. A nyers <span class="m">Ṙ</span> két dolgot mond egyszerre — benne van a test pillanatnyi pózja <em>és</em> a fordulás üteme —, ezért egyiket sem mondja tisztán: két azonosan pörgő test <span class="m">Ṙ</span>-je különbözik, pusztán mert máshogy állnak. Szorozzunk <span class="m">R<sup>⊤</sup></span>-tal: ez <button class="termbtn" id="so3gDroneInfo" type="button" aria-expanded="false" aria-controls="so3gDroneNote">visszahúzza a mozgást az identitásba</button>, oda, ahol a póznak már nincs hozzájárulása. Hogy melyik oldalról szorzunk, az megint a két frame:</p><p class="matline"><span class="m">Ω<sub>body</sub> = R<sup>⊤</sup> Ṙ</span></p><p class="matline"><span class="m">Ω<sub>world</sub> = Ṙ R<sup>⊤</sup></span></p><p>Drónnal: <span class="m">Ω<sub>body</sub></span> a <em>pilóta parancsa</em> — „pörögj a saját tengelyed körül, ennyivel” —, és állandó, amíg a parancs áll. A <span class="m">Ṙ</span> az, <em>amit a földi radar lát</em>: ugyanaz az állandó parancs folyamatosan <em>változó</em> <span class="m">Ṙ</span>-t termel, ahogy a gép elfordul. Ezért nem szabad egy gyroszkóp mérését közvetlenül a világ-frame integrálásába tenni — a gyro <span class="m">body</span>-ban mér.</p><div class="bubble" id="so3gDroneNote" role="dialog" aria-label="A visszahuzas es az adjungalt" hidden><p>A két frame ugyanazt a mozgást írja le, más könyveléssel, és az egyik a másikból az <em>adjungálttal</em> kapható meg:</p><p class="matline"><span class="m">Ω<sub>world</sub> = R Ω<sub>body</sub> R<sup>⊤</sup></span></p><p class="matline"><span class="m">ω<sub>world</sub> = R ω<sub>body</sub></span></p><p>Az első a mátrixalak, a második ugyanaz a <span class="m">ℝ<sup>3</sup></span>-beli tengelyvektoron. Ez a lehető legegyszerűbb Adjoint: <span class="m">Ad<sub>R</sub> = R</span>. <span class="m">SE(3)</span>-ban ugyanez már <span class="m">6×6</span>-os, és keveri a forgás- és az eltolásrészt — ott saját állomása van.</p><p>És vegyük észre: ez ugyanaz az „ugyanaz a mozgás, más nézőpontból” alak, mint fent a bal/jobb perturbációnál. A <span class="m">Ṙ</span> nem hibás — csak egy olyan bázisban van felírva, amelyik maga is mozog.</p></div><p>Csak <button class="termbtn" id="so3gCommInfo" type="button" aria-expanded="false" aria-controls="so3gCommNote">kis szögeknél alig látszik</button> — és pontosan ezért marad hetekig észrevétlen egy rossz Jacobian.</p><div class="bubble" id="so3gCommNote" role="dialog" aria-label="Miert nem latszik kis szogeknel" hidden><p>A Baker–Campbell–Hausdorff-formula első két tagja:</p><p class="matline"><span class="m">exp(ω<sub>1</sub>) exp(ω<sub>2</sub>) = exp(ω<sub>1</sub> + ω<sub>2</sub> + ½[ω<sub>1</sub>, ω<sub>2</sub>] + …)</span></p><p><span class="m">SO(3)</span>-ban a kommutátor éppen a vektoriális szorzat: <span class="m">[ω<sub>1</sub>, ω<sub>2</sub>] = ω<sub>1</sub> × ω<sub>2</sub></span>.</p><p>A hibatag tehát a szögek nagyságában <strong>másodrendű</strong>. Ha <span class="m">‖ω‖ ~ 10<sup>−3</sup></span>, a sorrendcsere hatása <span class="m">~10<sup>−6</sup></span> — a mérési zaj alatt.</p><p>Ez ugyanaz a mintázat, ami végigmegy az egész anyagon: <em>kis szögeknél nem látszik, nagyoknál hirtelen számít</em>. A rossz változat is konvergál, csak rosszabbul — ezért nem bukik ki a teszteken, és ezért harap loop closure-nél.</p></div>'},
        {t:'Gimbal lock: eltűnik egy szabadsági fok', b:'<p>Az Euler-szögek három forgatást ágyaznak egymásba — a jelenet három gyűrűje: a külső <span class="m">α</span>-val fordul, a középső <span class="m">β</span>-val, a belső <span class="m">γ</span>-val. Nézd, mi történik, ahogy a középső a 90°-hoz közelít: a belső gyűrű tengelye <strong>ráfordul</strong> a külsőére. A két tengely skaláris szorzata pontosan <span class="m">sin β</span> — 90°-nál 1, vagyis ott a két tárcsa ugyanazt a forgatást csinálja. Három tárcsa, két független irány: egy szabadsági fok eltűnt, és az <span class="m">(α, β, γ) ↦ R</span> leképezés deriváltja rangot veszít.</p><p>És nem egyetlen rossz pontról van szó, amit ki lehetne kerülni: a gimbal lock <em>közelében</em> már egy apró elfordulás is óriási tárcsasebességeket kíván. Az egész környezet rosszul kondicionált.</p><p>Miért pont a középső szög? Mert a külső kettő együtt nem csinál mást, mint <em>kijelöli a belső tengely irányát</em>: az <span class="m">α</span> annak a hosszúsága, a <span class="m">β</span> a szélessége. A gimbal lock ennek a gömbi térképnek a <strong>pólusa</strong>: ott futnak össze a délkörök, ott veszíti el a hosszúság a jelentését, és ott válik a „tekerd a hosszúságot” meg a „pörögj helyben” ugyanazzá a mozdulattá. Egyetlen síkba terített világtérkép sem ússza meg ezt a pontot — és nem a térképész hibájából.</p><p>Ennek a lapos térképlapnak szakszava is van: <strong>chart</strong> — egy görbült tér egy darabjának lapos koordinátázása. Az Euler-szögek egy chart az <span class="m">SO(3)</span>-on, és ez a chart elromlik a pólusán.</p><p>A szokásos reakció az, hogy ez az Euler-szögek ügyetlensége, és egy okosabb chart megjavítja. <strong>Nem javítja meg</strong> — és a következő két állomás pontosan erről szól. Nem <span class="m">SO(3)</span>-mal kezdjük, hanem ott, ahol a kérdés a legegyszerűbb: a körön.</p>'},
        {t:'Egy chart sosem elég — a kör', b:'<p>Előbb az a kérdés, amit eddig nem tettünk fel: <em>miért</em> akarunk egyáltalán lapos koordinátát? Mert minden, amit egy becsléssel csinálunk, vektortérbeli aritmetika: lépést <em>hozzáadunk</em>, lépéshosszal <em>szorzunk</em>, két becslést <em>átlagolunk</em>, és deriválunk. Ezt az <span class="m">ℝ<sup>n</sup></span> ingyen adja — ezért volt a lapos hold az alapvonal. Görbült téren egyik sem működik elemenként, és a lapos koordináta volna az az egy dolog, ami visszaadná őket. Ennyi a kérdés tétje.</p><p>Kezdjük a lehető legkisebb görbült téren. Az <span class="m">SO(2)</span> holdon láttuk: a <span class="m">θ</span> és a <span class="m">θ + 2π</span> ugyanaz a forgatás, tehát a paramétertér körbeér.</p><p class="matline"><span class="m">SO(2) ≅ S<sup>1</sup></span></p><p>Az <span class="m">S<sup>n</sup></span> jelölés innentől végigkísér, mondjuk hát ki egyszer: az <span class="m">S<sup>n</sup></span> az <span class="m">ℝ<sup>n+1</sup></span> egységgömbjének a <em>felülete</em>.</p><p class="matline"><span class="m">S<sup>n</sup> = { x ∈ ℝ<sup>n+1</sup> : ‖x‖ = 1 }</span></p><p>Tehát <span class="m">S<sup>1</sup></span> a kör (1 szabadsági fok), <span class="m">S<sup>2</sup></span> a gömb <em>felülete</em> (2), és így tovább — mindegyik görbült, és mindegyik önmagába zárul.</p><p>Próbáljuk meg a kört <em>egyetlen</em> charttal lefedni. A <span class="m">θ ∈ (−π, π)</span> a kör minden pontját megnevezi, egyetlenegy kivételével: a <span class="m">θ = π</span> forgatásét. Nézd a jelenetet: a zöld jelölő körbemegy, és a saját <span class="m">θ</span>-ja a résnél <span class="m">+π</span>-ről <span class="m">−π</span>-re <strong>ugrik</strong>. Ez a <em>varrat</em>. Told el a vágást bárhová: a varrat nem tűnik el, csak odébb megy.</p><p>Ez pedig nem ügyetlenség, hanem <button class="termbtn" id="so3gCircInfo" type="button" aria-expanded="false" aria-controls="so3gCircNote">kompaktság</button>. Egy tér <strong>kompakt</strong>, ha nem enged kifelé: nincs benne olyan sorozat, ami elszökik valahová, ami már nem a tér része. A kör ilyen. Egy <em>nyílt</em> intervallum nem — a végéhez tartó sorozat határértéke kiesik belőle. (<em>Nyílt</em>: a peremét nem tartalmazza, mert egy koordinátának minden pontja körül kell egy kis mozgástér.) Kompaktat és nem-kompaktat pedig nem lehet oda-vissza folytonosan megfeleltetni — tehát a kör egyetlen charttal nem fedhető le, akárhogy ügyeskedünk.</p><p>Kettővel viszont igen. A jelenetben a második, türkiz ív a varratra ül rá, mindkét oldalon átfedéssel. Több chart, átfedésekkel — ennek is van neve: <strong>atlasz</strong>. Ez a becsületes válasz egy görbült térre, de vegyük észre, mit adtunk fel: nem <em>egy</em> lapos koordinátánk lett, hanem több, ragasztással.</p><p>Van egy második, az elsőtől független módja is annak, hogy két teret megkülönböztessünk: <strong>számoljuk meg a hurkokat</strong>. Hányféle, egymásba folytonosan át nem deformálható hurok van a téren? A körön annyi, ahányszor körbeérsz — a körüljárási szám, tehát egy egész szám. Lapos téren viszont minden hurok összehúzható egy pontba: egyetlenegy fajta van. Ennek a hurokszámlálásnak a neve <span class="m">π<sub>1</sub></span>.</p><p class="matline"><span class="m">π<sub>1</sub>(S<sup>1</sup>) = ℤ</span></p><p class="matline"><span class="m">π<sub>1</sub>(ℝ<sup>n</sup>) = 0</span></p><p>Két tér, aminek más a <span class="m">π<sub>1</sub></span>-e, nem lehet ugyanaz a tér másképp rajzolva. A körre tehát <em>két</em> független akadály is áll, és mindkettő átvihető egy dimenzióval feljebb.</p><div class="bubble" id="so3gCircNote" role="dialog" aria-label="A kompaktsag pontosan" hidden><p><strong>Kompaktság.</strong> Zárt és korlátos (Heine–Borel), és ezzel egyenértékűen: minden végtelen sorozatnak van a téren <em>belül</em> konvergens részsorozata. A <span class="m">(−π, π)</span> intervallumban ez elromlik: a <span class="m">π</span>-hez tartó sorozat határértéke már nincs a halmazban.</p><p><strong>És miért dönt ez el bármit?</strong> Kompakt tér folytonos képe kompakt. Ha volna oda-vissza folytonos megfeleltetés a kör és egy nyílt intervallum között, akkor az intervallum a kör folytonos képe volna, tehát kompakt — de nem az. Ellentmondás, és a bizonyítás nem használt sem szöget, sem koordinátát.</p></div>'},
        {t:'A gimbal lock tétel, nem bosszúság', b:'<p>Eggyel feljebb a létrán: <span class="m">S<sup>2</sup></span>, a gömbfelület. A szélesség és a hosszúság egy chart rajta — ugyanaz, amivel két állomással ezelőtt a belső tengely irányát adtuk meg. A jelenetben a két borostyán jelölő végig <em>ugyanakkora</em> hosszúságkülönbséget tart, a köztük lévő ív mégis elfogy, ahogy a pólus felé kúsznak: a hossza <span class="m">R·Δλ·cos φ</span>, és a <span class="m">cos φ</span> hal el. Ugyanaz az összeomlás, mint a gyűrűkön. És figyeld meg, mi <em>nem</em> mentette meg: a gömbfelületen minden hurok összehúzható, <span class="m">π<sub>1</sub>(S<sup>2</sup>) = 0</span>, mint a lapos téren — mégsem fedhető le egy charttal, mert kompakt. A kompaktság az erősebb, magában is működő akadály; a hurkok a második, tőle független.</p><p>És most az a létrafok, ami minket érdekel. Az <span class="m">SO(3)</span> 3-dimenziós és kompakt, a hurkai pedig meglepőek: a 360°-os forgatás hurka <strong>nem</strong> húzható össze, a 720°-osé viszont igen. Nem végtelen sok osztály, mint a körön, hanem pontosan <button class="termbtn" id="so3gTopInfo" type="button" aria-expanded="false" aria-controls="so3gTopNote">kettő</button>.</p><p>Ezzel minden együtt van. Egy globális lapos koordináta definíció szerint <em>diffeomorfizmus</em> lenne — oda-vissza sima átcímkézés, tépés és ragasztás nélkül — az <span class="m">SO(3)</span> és az <span class="m">ℝ<sup>3</sup></span> egy nyílt darabja között. Az ilyen átcímkézés viszont minden topológiai invariánst megőriz, és itt kettő is elromlik, egymástól függetlenül:</p><p class="matline"><span class="m">SO(3) kompakt</span></p><p class="matline"><span class="m">ℝ<sup>3</sup> nyílt részei nem</span></p><p class="matline"><span class="m">π<sub>1</sub>(SO(3)) = ℤ/2</span></p><p class="matline"><span class="m">π<sub>1</sub>(ℝ<sup>3</sup>) = 0</span></p><p class="matline"><span class="m">nincs globális, szingularitásmentes 3-paraméteres koordináta SO(3)-ra</span></p><p>A kompaktság önmagában elég — szó szerint az az érv, amit a körön végigvittünk. És nem a darabszám a baj: az <span class="m">SO(3)</span> pontosan 3-dimenziós, három szám éppen a helyes mennyiség. A <em>lapos</em> <span class="m">ℝ<sup>3</sup></span> <em>alakja</em> rossz: sehol nem ér körbe és sehol nincs vége.</p><p>Azt viszont a tétel nem mondja meg, hogy <em>mivel</em> fizetünk. Az Euler-szögek rangvesztéssel: ez a gimbal lock. A Rodrigues-vektor varrattal — a <span class="m">θ = π</span> gömbhéjon a <span class="m">+πa</span> és a <span class="m">−πa</span> ugyanaz a forgatás —, a deriváltja viszont addig végig teljes rangú marad. Ez dönt a gyakorlatban: egy kicsi inkrementum sosem jut a <span class="m">π</span> közelébe, egy tárolt abszolút póz viszont bármikor ott lehet.</p><p>Most már a menekülési utak is olvashatók. A <strong>kvaternió</strong> eggyel feljebb lép a most bejárt létrán: az <span class="m">S<sup>3</sup></span>-ra, az <span class="m">ℝ<sup>4</sup></span> egységgömbjének felületére. Az <span class="m">S<sup>3</sup></span> 3-dimenziós, sima, és nincs rajta se varrat, se rangvesztés — de ezt egy <em>kényszerrel</em> (<span class="m">‖q‖ = 1</span>) vettük meg, és ugyanúgy kompakt és görbült, mint a többi létrafok. Vagyis nem <em>lapos</em>, márpedig épp azt akartuk: az összeadást, a skálázást, a deriválást. Az <strong>atlasz</strong> — több chart, ahogy a körön — működik, csak épp nem teljesíti a „globális lapos koordináta” ambíciót, hanem feladja.</p><p>A gyakorlati válasz ezért nem a kettő közti választás, hanem munkamegosztás. Ahol a globalitás számít, ott <em>redundánsan</em> tároljuk a forgatást, mátrixként vagy kvaternióként. Ahol viszont a tétel nem tilt semmit — a lokális érintőtérben —, ott 3-vektorként vesszük a <em>növekményt</em>, és ott az összeadás megint az, aminek lennie kell. Hogy ez pontosan hogyan működik, és hogy milyen az <span class="m">SO(3)</span> igazi, <span class="m">ℤ/2</span>-es alakja, azt a <em>Riemann-gradiens</em> hold mutatja meg.</p><div class="bubble" id="so3gTopNote" role="dialog" aria-label="A hurkok es a diffeomorfizmus" hidden><p><strong>π<sub>1</sub>, a fundamentális csoport.</strong> A hurkokat folytonos deformáció erejéig osztályozza, és az osztályok <em>csoportot</em> alkotnak; a művelet a hurkok egymás után fűzése. A <span class="m">ℤ/2</span> tehát azt mondja, hogy <span class="m">1 + 1 = 0</span>: a nem összehúzható hurok <em>duplája</em> már összehúzható. Ezt mutatja a szíjtrükk: egy 360°-kal megcsavart szíj nem simítható ki a végei elengedése nélkül, egy 720°-kal megcsavart igen.</p><p><strong>Diffeomorfizmus.</strong> Sima, invertálható megfeleltetés, amelynek az <em>inverze is sima</em>. Egy koordinátaváltás pontosan ez — ezért fordul a „nem lehetne laposra transzformálni?” kérdés arra, hogy létezik-e diffeomorfizmus <span class="m">SO(3)</span> és <span class="m">ℝ<sup>3</sup></span> egy nyílt része között. És mivel minden topológiai invariánst megőriz, egyetlen eltérő invariáns is megöli.</p></div>'}
      ],
      en: [
        {t:'Every Rotation Has an Axis', b:'<p>What does an <span class="m">R ∈ SO(3)</span> <em>actually</em> do? The answer is Euler’s theorem, and it is surprisingly strong: <strong>every</strong> rotation has an axis — a line it leaves where it is.</p><p>Not “most of them”, not “the nice ones”. All of them, and the <button class="termbtn" id="so3gEulerInfo" type="button" aria-expanded="false" aria-controls="so3gEulerNote">proof is three lines</button>.</p><p>The scene shows it: the green line stands still while every other point traces a circle around it. That is why every rotation can be written</p><p class="matline"><span class="m">R = R(a, θ)</span></p><p class="matline"><span class="m">‖a‖ = 1</span></p><p>a unit vector <span class="m">a</span> and an angle <span class="m">θ</span>. Count the degrees of freedom from here: <span class="m">a</span> is a point of the unit sphere, worth <strong>2</strong>; <span class="m">θ</span> is one number, worth <strong>1</strong>. Total <strong>3</strong> — the same three that falls out of the constraint <span class="m">R<sup>⊤</sup>R = I</span>, arrived at along a completely different road.</p><p>And now the point of putting this first: axis and angle multiply into a <em>single</em> vector.</p><p class="matline"><span class="m">ω = a θ ∈ ℝ<sup>3</sup></span></p><p>That is an ordinary 3-vector: you can add it, scale it, differentiate it. It is the tangent vector that <span class="m">exp</span> carries back into the group. The space <span class="m">ω</span> lives in is flat; the space <span class="m">R</span> lives in is not — and the traffic between them is the whole machine.</p><p>One catch: <span class="m">exp</span> does not accept vectors. Its series — <span class="m">I + X + ½X<sup>2</sup> + …</span> — needs an <span class="m">X</span> that can be multiplied by itself, and <span class="m">ω</span> is a column of three numbers. The <button class="termbtn" id="so3gHatInfo" type="button" aria-expanded="false" aria-controls="so3gHatNote">hat</button> closes that gap: it lays the three numbers out as the matrix that reproduces the cross product.</p><p class="matline"><span class="m">ω<sup>∧</sup> =</span><span class="matrix"><span class="mbracket"></span><span class="mgrid"><span>0</span><span>&minus;ω<sub>3</sub></span><span>ω<sub>2</sub></span><span>ω<sub>3</sub></span><span>0</span><span>&minus;ω<sub>1</sub></span><span>&minus;ω<sub>2</sub></span><span>ω<sub>1</sub></span><span>0</span></span><span class="mbracket right"></span></span></p><p class="matline"><span class="m">ω<sup>∧</sup> v = ω × v</span></p><p>Now <span class="m">R = exp(ω<sup>∧</sup>)</span> is well-formed, and the flat space those matrices form — closed under addition and scaling, unlike <span class="m">SO(3)</span> itself — is the Lie algebra <span class="m">so(3)</span>. The hat is linear, so <span class="m">ω<sup>∧</sup> = (aθ)<sup>∧</sup> = θ a<sup>∧</sup></span>: the <span class="m">exp(â θ)</span> that the <span class="m">SO(2)</span> moon put in its table of three encodings is this same expression, and <span class="m">SE(3)</span> reuses the operator unchanged as the rotation block of its 4×4.</p><div class="bubble" id="so3gHatNote" role="dialog" aria-label="Why skew-symmetric" hidden><p>Skew-symmetry is <strong>forced</strong>, not chosen. Differentiate the constraint <span class="m">R<sup>⊤</sup>R = I</span> along a motion:</p><p class="matline"><span class="m">Ṙ<sup>⊤</sup>R + R<sup>⊤</sup>Ṙ = 0 ⟹ (R<sup>⊤</sup>Ṙ)<sup>⊤</sup> = −R<sup>⊤</sup>Ṙ</span></p><p>So every legal velocity, written at the identity, is a skew-symmetric matrix. Now count the free entries of one: the diagonal is zero and the lower triangle is minus the upper, leaving <strong>3</strong>. The same 3 as the axis-and-angle count above, and the same 3 the constraint left — a third road to the same number.</p><p>The inverse map takes the matrix back to the vector, written <span class="m">∨</span>:</p><p class="matline"><span class="m">(ω<sup>∧</sup>)<sup>∨</sup> = ω</span></p></div><div class="bubble" id="so3gEulerNote" role="dialog" aria-label="Proof of Euler theorem" hidden><p>We must show that <span class="m">1</span> is an eigenvalue of <span class="m">R</span>, i.e. <span class="m">det(R − I) = 0</span>. Use <span class="m">R R<sup>⊤</sup> = I</span> and <span class="m">det R = 1</span>:</p><p class="matline"><span class="m">det(R − I) = det(R − R R<sup>⊤</sup>) = det R · det(I − R<sup>⊤</sup>)</span></p><p class="matline"><span class="m">= det((I − R)<sup>⊤</sup>) = det(I − R) = (−1)<sup>3</sup> det(R − I)</span></p><p>So <span class="m">det(R − I) = −det(R − I)</span>, hence <span class="m">det(R − I) = 0</span>. There is a non-zero <span class="m">a</span> with <span class="m">R a = a</span>: the axis.</p><p>Notice where the <strong>odd</strong> dimension does its work: in the factor <span class="m">(−1)<sup>3</sup></span>. In even dimensions the proof breaks, and rightly so — a planar rotation (<span class="m">SO(2)</span>) has <em>no</em> fixed direction, only a fixed point.</p></div>'},
        {t:'Order Matters, in 3D', b:'<p><span class="m">SO(2)</span> was commutative. <span class="m">SE(2)</span> was not — but there the non-commutativity came from the translation, while the rotation part still behaved. Here the rotation itself goes wrong.</p><p>Take two right angles: a rotation about the world’s <span class="m">z</span> axis, and one about the world’s <span class="m">y</span> axis. Follow the violet direction <span class="m">e<sub>z</sub></span>.</p><p class="matline"><span class="m">z first, then y:&nbsp; e<sub>z</sub> → e<sub>z</sub> → e<sub>x</sub></span></p><p class="matline"><span class="m">y first, then z:&nbsp; e<sub>z</sub> → e<sub>x</sub> → e<sub>y</sub></span></p><p>The same two moves, and the violet axis ends up pointing at <span class="m">x</span> in one case and at <span class="m">y</span> in the other. Not a subtle discrepancy: <strong>90°</strong>.</p><p class="matline"><span class="m">R<sub>y</sub> R<sub>z</sub> ≠ R<sub>z</sub> R<sub>y</sub></span></p><p>This is the “one new thing” <span class="m">SO(3)</span> adds, and it reaches further than it first appears. If the order of multiplication matters, then it also matters whether a perturbation <span class="m">δ</span> multiplies the estimate <strong>from the left or from the right</strong>:</p><p class="matline"><span class="m">exp(δ) R</span>&nbsp;&nbsp;or&nbsp;&nbsp;<span class="m">R exp(δ)</span></p><p>The first perturbs in the world’s coordinates, the second in the body’s. That is the <em>body vs. world</em> distinction, and its entire content is this one inequality. Which side we call “body” is a <em>convention</em>; that the two <em>differ</em> is a <em>theorem</em>.</p><p>And the same thing <em>in motion</em>. The raw <span class="m">Ṙ</span> says two things at once — it carries the body’s current pose <em>and</em> its rate of turn — so it says neither cleanly: two identically spinning bodies have different <span class="m">Ṙ</span>, purely because they are held differently. Multiply by <span class="m">R<sup>⊤</sup></span>: that <button class="termbtn" id="so3gDroneInfo" type="button" aria-expanded="false" aria-controls="so3gDroneNote">pulls the motion back to the identity</button>, where the pose no longer contributes. Which side you multiply from is, again, the two frames:</p><p class="matline"><span class="m">Ω<sub>body</sub> = R<sup>⊤</sup> Ṙ</span></p><p class="matline"><span class="m">Ω<sub>world</sub> = Ṙ R<sup>⊤</sup></span></p><p>On a drone: <span class="m">Ω<sub>body</sub></span> is the <em>pilot’s command</em> — “roll about your own axis, this fast” — and it stays constant while the command does. <span class="m">Ṙ</span> is <em>what the ground radar sees</em>: the same constant command produces a continuously <em>changing</em> <span class="m">Ṙ</span> as the aircraft turns. This is why a gyroscope reading must not be integrated directly in the world frame — a gyro measures in <span class="m">body</span>.</p><div class="bubble" id="so3gDroneNote" role="dialog" aria-label="The pull-back and the adjoint" hidden><p>The two frames describe the same motion with different bookkeeping, and one is obtained from the other by the <em>adjoint</em>:</p><p class="matline"><span class="m">Ω<sub>world</sub> = R Ω<sub>body</sub> R<sup>⊤</sup></span></p><p class="matline"><span class="m">ω<sub>world</sub> = R ω<sub>body</sub></span></p><p>The first is the matrix form, the second the same statement on the axis vector in <span class="m">ℝ<sup>3</sup></span>. This is the simplest adjoint there is: <span class="m">Ad<sub>R</sub> = R</span>. In <span class="m">SE(3)</span> it becomes <span class="m">6×6</span> and mixes the rotational and translational parts — where it gets a station of its own.</p><p>And note the shape: it is the same “same motion, different viewpoint” form as the left/right perturbation above. <span class="m">Ṙ</span> is not wrong — it is merely written in a basis that is itself moving.</p></div><p>It is just that <button class="termbtn" id="so3gCommInfo" type="button" aria-expanded="false" aria-controls="so3gCommNote">at small angles you can barely see it</button> — which is exactly why a wrong Jacobian survives for weeks.</p><div class="bubble" id="so3gCommNote" role="dialog" aria-label="Why small angles hide it" hidden><p>The first two terms of the Baker–Campbell–Hausdorff formula:</p><p class="matline"><span class="m">exp(ω<sub>1</sub>) exp(ω<sub>2</sub>) = exp(ω<sub>1</sub> + ω<sub>2</sub> + ½[ω<sub>1</sub>, ω<sub>2</sub>] + …)</span></p><p>In <span class="m">SO(3)</span> the commutator is exactly the cross product: <span class="m">[ω<sub>1</sub>, ω<sub>2</sub>] = ω<sub>1</sub> × ω<sub>2</sub></span>.</p><p>So the error term is <strong>second order</strong> in the size of the angles. With <span class="m">‖ω‖ ~ 10<sup>−3</sup></span>, swapping the order costs <span class="m">~10<sup>−6</sup></span> — below the measurement noise.</p><p>This is the pattern that runs through the whole subject: <em>invisible at small angles, suddenly decisive at large ones</em>. The wrong version converges too, just worse — which is why it passes the tests, and why it bites at loop closure.</p></div>'},
        {t:'Gimbal Lock: a Degree of Freedom Vanishes', b:'<p>Euler angles stack three rotations inside one another — the three rings in the scene: the outer one turns by <span class="m">α</span>, the middle one by <span class="m">β</span>, the inner one by <span class="m">γ</span>. Watch what happens as the middle one approaches 90°: the inner ring’s axis <strong>swings onto</strong> the outer one’s. The dot product of the two axes is exactly <span class="m">sin β</span> — at 90° that is 1, so there the two dials perform the same rotation. Three dials, two independent directions: a degree of freedom has vanished, and the derivative of the map <span class="m">(α, β, γ) ↦ R</span> loses rank.</p><p>Nor is it one bad point you could step around: <em>near</em> the lock, even a tiny turn demands enormous dial rates. The whole neighbourhood is ill-conditioned.</p><p>Why the middle angle in particular? Because the outer two do nothing but <em>point the inner axis</em>: <span class="m">α</span> is its longitude and <span class="m">β</span> its latitude. Gimbal lock is the <strong>pole</strong> of that spherical map: it is where the meridians meet, where longitude loses its meaning, and where “turn the longitude dial” and “spin in place” become the same motion. No flat map of the globe escapes that point — and not through any fault of the map-maker.</p><p>Such a flat map sheet has a technical name: a <strong>chart</strong> — a flat coordinatisation of one piece of a curved space. Euler angles are a chart on <span class="m">SO(3)</span>, and this chart breaks at its pole.</p><p>The usual reaction is that this is clumsiness on the part of Euler angles, and that a smarter chart repairs it. <strong>It does not</strong> — and the next two stations are exactly why. We do not start with <span class="m">SO(3)</span> but where the question is simplest: on the circle.</p>'},
        {t:'One Chart Is Never Enough: the Circle', b:'<p>First the question we have not yet asked: <em>why</em> do we want a flat coordinate at all? Because everything we do with an estimate is vector-space arithmetic: we <em>add</em> a step, <em>scale</em> it by a step length, <em>average</em> two estimates, and differentiate. <span class="m">ℝ<sup>n</sup></span> gives all of that for free — which is why the flat moon was the baseline. On a curved space none of it works entrywise, and a flat coordinate would be the one thing that gave it back. That is what is at stake.</p><p>Start on the smallest curved space there is. On the <span class="m">SO(2)</span> moon we saw that <span class="m">θ</span> and <span class="m">θ + 2π</span> are the same rotation, so the parameter space wraps around.</p><p class="matline"><span class="m">SO(2) ≅ S<sup>1</sup></span></p><p>The notation <span class="m">S<sup>n</sup></span> will follow us from here on, so let us say it once: <span class="m">S<sup>n</sup></span> is the <em>surface</em> of the unit sphere in <span class="m">ℝ<sup>n+1</sup></span>.</p><p class="matline"><span class="m">S<sup>n</sup> = { x ∈ ℝ<sup>n+1</sup> : ‖x‖ = 1 }</span></p><p>So <span class="m">S<sup>1</sup></span> is the circle (1 degree of freedom), <span class="m">S<sup>2</sup></span> is the <em>surface</em> of the ball (2), and so on — each one curved, each one closing on itself.</p><p>Try covering the circle with <em>one</em> chart. <span class="m">θ ∈ (−π, π)</span> names every point of the circle but one: the rotation at <span class="m">θ = π</span>. Watch the scene: the green marker goes round, and its own <span class="m">θ</span> <strong>jumps</strong> from <span class="m">+π</span> to <span class="m">−π</span> at the gap. That is the <em>seam</em>. Slide the cut anywhere you like: the seam does not disappear, it only moves.</p><p>And that is not clumsiness, it is <button class="termbtn" id="so3gCircInfo" type="button" aria-expanded="false" aria-controls="so3gCircNote">compactness</button>. A space is <strong>compact</strong> if it lets nothing out: it holds no sequence escaping to somewhere that is no longer part of the space. The circle is like that. An <em>open</em> interval is not — the limit of a sequence heading for its end falls out of it. (<em>Open</em>: it does not contain its boundary, because a coordinate needs a little room around every one of its points.) And a compact space cannot be put in continuous both-ways correspondence with a non-compact one — so no amount of cleverness covers the circle with a single chart.</p><p>Two charts do cover it. In the scene the second, teal arc sits over the seam, overlapping on both sides. Several charts with overlaps — that has a name too: an <strong>atlas</strong>. It is the honest answer for a curved space, but notice what we gave up: we do not have <em>one</em> flat coordinate, we have several, glued.</p><p>There is a second, independent way to tell two spaces apart: <strong>count the loops</strong>. How many kinds of loop does a space have that cannot be continuously deformed into one another? On the circle, as many as the number of times you go round — the winding number, an integer. On a flat space every loop contracts to a point: exactly one kind. That loop count is called <span class="m">π<sub>1</sub></span>.</p><p class="matline"><span class="m">π<sub>1</sub>(S<sup>1</sup>) = ℤ</span></p><p class="matline"><span class="m">π<sub>1</sub>(ℝ<sup>n</sup>) = 0</span></p><p>Two spaces with different <span class="m">π<sub>1</sub></span> cannot be the same space drawn differently. So the circle already carries <em>two</em> independent obstructions — and both of them carry one dimension up.</p><div class="bubble" id="so3gCircNote" role="dialog" aria-label="Compactness, precisely" hidden><p><strong>Compactness.</strong> Closed and bounded (Heine–Borel), equivalently: every infinite sequence has a subsequence converging <em>inside</em> the space. In the interval <span class="m">(−π, π)</span> that fails: the limit of a sequence heading for <span class="m">π</span> is no longer in the set.</p><p><strong>And why does that settle anything?</strong> The continuous image of a compact space is compact. If there were a continuous both-ways correspondence between the circle and an open interval, the interval would be the continuous image of the circle, hence compact — but it is not. A contradiction, and the argument used neither an angle nor a coordinate.</p></div>'},
        {t:'Gimbal Lock Is a Theorem, Not a Nuisance', b:'<p>One rung up: <span class="m">S<sup>2</sup></span>, the surface of the ball. Latitude and longitude are a chart on it — the very one we used two stations ago to point the inner axis. In the scene the two amber markers keep the <em>same</em> difference in longitude throughout, yet the arc between them runs out as they climb towards the pole: its length is <span class="m">R·Δλ·cos φ</span>, and it is <span class="m">cos φ</span> that dies. The same collapse as on the rings. And note what did <em>not</em> save it: on the sphere every loop contracts, <span class="m">π<sub>1</sub>(S<sup>2</sup>) = 0</span> just as on a flat space — and it still cannot be covered by one chart, because it is compact. Compactness is the stronger obstruction, the one that works alone; the loops are a second one, independent of it.</p><p>And now the rung we care about. <span class="m">SO(3)</span> is 3-dimensional and compact, and its loops are the surprise: the loop of a 360° rotation <strong>does not</strong> contract, while the 720° one does. Not infinitely many classes as on the circle, but exactly <button class="termbtn" id="so3gTopInfo" type="button" aria-expanded="false" aria-controls="so3gTopNote">two</button>.</p><p>That is everything we need. A global flat coordinate would by definition be a <em>diffeomorphism</em> — a relabelling smooth in both directions, with no tearing and no gluing — between <span class="m">SO(3)</span> and an open piece of <span class="m">ℝ<sup>3</sup></span>. But such a relabelling preserves every topological invariant, and two of them break here, independently:</p><p class="matline"><span class="m">SO(3) is compact</span></p><p class="matline"><span class="m">open subsets of ℝ<sup>3</sup> are not</span></p><p class="matline"><span class="m">π<sub>1</sub>(SO(3)) = ℤ/2</span></p><p class="matline"><span class="m">π<sub>1</sub>(ℝ<sup>3</sup>) = 0</span></p><p class="matline"><span class="m">there is no global, singularity-free 3-parameter coordinate for SO(3)</span></p><p>Compactness alone is enough — literally the argument we worked through on the circle. And the count is not the problem: <span class="m">SO(3)</span> is exactly 3-dimensional, so three numbers are precisely the right amount. It is the <em>shape</em> of flat <span class="m">ℝ<sup>3</sup></span> that is wrong: it never wraps around and it never ends.</p><p>What the theorem does not say is <em>what</em> you pay with. Euler angles pay in lost rank: that is gimbal lock. The Rodrigues vector pays with a seam — on the shell <span class="m">θ = π</span> the vectors <span class="m">+πa</span> and <span class="m">−πa</span> are the same rotation — while out to that shell its derivative stays full-rank. In practice that difference decides everything: a small increment never comes near <span class="m">π</span>, whereas a stored absolute pose can be sitting there at any moment.</p><p>Now the escape routes can be read too. The <strong>quaternion</strong> steps one rung up the ladder we have just climbed: to <span class="m">S<sup>3</sup></span>, the surface of the unit sphere in <span class="m">ℝ<sup>4</sup></span>. <span class="m">S<sup>3</sup></span> is 3-dimensional, smooth, with neither a seam nor a rank collapse — but we bought that with a <em>constraint</em> (<span class="m">‖q‖ = 1</span>), and it is compact and curved like every other rung. So it is not <em>flat</em>, and flat is precisely what we were after: adding, scaling, differentiating. An <strong>atlas</strong> — several charts, as on the circle — does work, but it abandons the ambition of a global flat coordinate rather than meeting it.</p><p>The practical answer is therefore not a choice between the two but a division of labour. Where being global is what matters, store the rotation <em>redundantly</em>, as a matrix or a quaternion. Where the theorem forbids nothing — in the local tangent space — take the <em>increment</em> as a 3-vector, and there addition is again what it should be. Exactly how that works, and what <span class="m">SO(3)</span>’s true, <span class="m">ℤ/2</span>-shaped form looks like, is what the <em>Riemannian gradient</em> moon shows.</p><div class="bubble" id="so3gTopNote" role="dialog" aria-label="The loops and the diffeomorphism" hidden><p><strong>π<sub>1</sub>, the fundamental group.</strong> It classifies loops up to continuous deformation, and the classes form a <em>group</em>; the operation is concatenating loops. So <span class="m">ℤ/2</span> says <span class="m">1 + 1 = 0</span>: the <em>double</em> of the non-contractible loop does contract. That is what the belt trick demonstrates — a belt with one 360° twist cannot be flattened without letting go of its ends, one with 720° can.</p><p><strong>Diffeomorphism.</strong> A smooth, invertible correspondence whose <em>inverse is also smooth</em>. A change of coordinates is exactly that — which is why “could we not transform it flat?” turns into: does a diffeomorphism exist between <span class="m">SO(3)</span> and an open piece of <span class="m">ℝ<sup>3</sup></span>? And since it preserves every topological invariant, a single differing invariant kills it.</p></div>'}
      ],
      ja: [
        {t:'どの回転にも軸がある', b:'<p><span class="m">R ∈ SO(3)</span> は<em>実際には</em>何をしているのか。答えは Euler の定理で、驚くほど強い主張です: <strong>どの</strong>回転にも軸がある — その場に残す直線がある、ということです。</p><p>「たいていの回転には」でも「行儀のよい回転には」でもありません。すべてに、です。しかも<button class="termbtn" id="so3gEulerInfo" type="button" aria-expanded="false" aria-controls="so3gEulerNote">証明は三行</button>。</p><p>シーンがそれを見せています: 緑の直線は静止し、他のどの点もそのまわりに円を描きます。だからどの回転もこう書けます:</p><p class="matline"><span class="m">R = R(a, θ)</span></p><p class="matline"><span class="m">‖a‖ = 1</span></p><p>単位ベクトル <span class="m">a</span> と角 <span class="m">θ</span>。ここから自由度を数えましょう: <span class="m">a</span> は単位球面上の点で <strong>2</strong>、<span class="m">θ</span> は数一つで <strong>1</strong>。合わせて <strong>3</strong> — 拘束 <span class="m">R<sup>⊤</sup>R = I</span> から出てくるのと同じ 3 に、まったく別の道から着きました。</p><p>そしてこれを先に置く理由: 軸と角は<em>一つの</em>ベクトルに掛け合わせられます。</p><p class="matline"><span class="m">ω = a θ ∈ ℝ<sup>3</sup></span></p><p>これはふつうの 3 次元ベクトルです: 足せる、スケールできる、微分できる。これこそ <span class="m">exp</span> が群へ戻す接ベクトルです。<span class="m">ω</span> の住む空間は平坦で、<span class="m">R</span> の住む空間はそうではない — この二つの間の往復が、機械のすべてです。</p><p>ひとつ引っかかりがあります: <span class="m">exp</span> はベクトルを受け取りません。その級数 — <span class="m">I + X + ½X<sup>2</sup> + …</span> — は自分自身と掛けられる <span class="m">X</span> を要求しますが、<span class="m">ω</span> は三つの数の列です。<button class="termbtn" id="so3gHatInfo" type="button" aria-expanded="false" aria-controls="so3gHatNote">ハット</button>がその隙間を埋めます: 三つの数を、外積を再現する行列に並べ替えるのです。</p><p class="matline"><span class="m">ω<sup>∧</sup> =</span><span class="matrix"><span class="mbracket"></span><span class="mgrid"><span>0</span><span>&minus;ω<sub>3</sub></span><span>ω<sub>2</sub></span><span>ω<sub>3</sub></span><span>0</span><span>&minus;ω<sub>1</sub></span><span>&minus;ω<sub>2</sub></span><span>ω<sub>1</sub></span><span>0</span></span><span class="mbracket right"></span></span></p><p class="matline"><span class="m">ω<sup>∧</sup> v = ω × v</span></p><p>これで <span class="m">R = exp(ω<sup>∧</sup>)</span> が意味を持ちます。そしてこれらの行列がつくる平坦な空間 — <span class="m">SO(3)</span> 自身とは違い、足し算とスケールについて閉じています — が Lie 代数 <span class="m">so(3)</span> です。ハットは線形なので <span class="m">ω<sup>∧</sup> = (aθ)<sup>∧</sup> = θ a<sup>∧</sup></span>: <span class="m">SO(2)</span> の衛星が三つの符号化の表に書いた <span class="m">exp(â θ)</span> は、まさにこの式のことでした。<span class="m">SE(3)</span> はこの演算子をそのまま、4×4 の回転ブロックとして再利用します。</p><div class="bubble" id="so3gHatNote" role="dialog" aria-label="なぜ歪対称か" hidden><p>歪対称であることは<strong>強制</strong>であって、選択ではありません。拘束 <span class="m">R<sup>⊤</sup>R = I</span> を運動に沿って微分します:</p><p class="matline"><span class="m">Ṙ<sup>⊤</sup>R + R<sup>⊤</sup>Ṙ = 0 ⟹ (R<sup>⊤</sup>Ṙ)<sup>⊤</sup> = −R<sup>⊤</sup>Ṙ</span></p><p>つまり許される速度は、単位元で書けばすべて歪対称行列です。その自由な成分を数えてみましょう: 対角は 0、下三角は上三角の符号違いなので、残るのは <strong>3</strong>。上の軸と角から数えた 3 と同じ、拘束が残した 3 とも同じ — 同じ数への三本目の道です。</p><p>逆の写像は行列をベクトルへ戻すもので、<span class="m">∨</span> と書きます:</p><p class="matline"><span class="m">(ω<sup>∧</sup>)<sup>∨</sup> = ω</span></p></div><div class="bubble" id="so3gEulerNote" role="dialog" aria-label="Euler の定理の証明" hidden><p><span class="m">1</span> が <span class="m">R</span> の固有値であること、すなわち <span class="m">det(R − I) = 0</span> を示します。<span class="m">R R<sup>⊤</sup> = I</span> と <span class="m">det R = 1</span> を使って:</p><p class="matline"><span class="m">det(R − I) = det(R − R R<sup>⊤</sup>) = det R · det(I − R<sup>⊤</sup>)</span></p><p class="matline"><span class="m">= det((I − R)<sup>⊤</sup>) = det(I − R) = (−1)<sup>3</sup> det(R − I)</span></p><p>したがって <span class="m">det(R − I) = −det(R − I)</span>、ゆえに <span class="m">det(R − I) = 0</span>。<span class="m">R a = a</span> となる非零の <span class="m">a</span> が存在します: それが軸です。</p><p><strong>奇数</strong>次元がどこで効いているかに注目してください: <span class="m">(−1)<sup>3</sup></span> の因子です。偶数次元では証明が壊れますが、それは正当です — 平面回転（<span class="m">SO(2)</span>）には不動の<em>方向</em>はなく、不動点があるだけだからです。</p></div>'},
        {t:'3D でも順序が効く', b:'<p><span class="m">SO(2)</span> は可換でした。<span class="m">SE(2)</span> はもう可換ではありませんでしたが、そこでの非可換性は並進から来ていて、回転部分はまだ行儀よくしていました。ここでは回転そのものが壊れます。</p><p>直角を二つ取ります: 世界の <span class="m">z</span> 軸まわりの回転と、世界の <span class="m">y</span> 軸まわりの回転。菫色の向き <span class="m">e<sub>z</sub></span> を追ってください。</p><p class="matline"><span class="m">先に z、次に y:&nbsp; e<sub>z</sub> → e<sub>z</sub> → e<sub>x</sub></span></p><p class="matline"><span class="m">先に y、次に z:&nbsp; e<sub>z</sub> → e<sub>x</sub> → e<sub>y</sub></span></p><p>同じ二つの動作なのに、菫色の軸は一方では <span class="m">x</span> を、他方では <span class="m">y</span> を指して終わります。微妙な食い違いではありません: <strong>90°</strong> です。</p><p class="matline"><span class="m">R<sub>y</sub> R<sub>z</sub> ≠ R<sub>z</sub> R<sub>y</sub></span></p><p>これが <span class="m">SO(3)</span> の加える「一つの新しいこと」であり、見た目より遠くまで波及します。掛ける順序が効くなら、摂動 <span class="m">δ</span> を推定値に<strong>左から掛けるか右から掛けるか</strong>も効くからです:</p><p class="matline"><span class="m">exp(δ) R</span>&nbsp;&nbsp;または&nbsp;&nbsp;<span class="m">R exp(δ)</span></p><p>前者は世界の座標で、後者は物体の座標で摂動します。これが <em>body / world</em> の区別であり、その中身はまるごとこの一つの不等式です。どちらを「body」と呼ぶかは<em>約束</em>、二つが<em>異なる</em>ことは<em>定理</em>です。</p><p>そして<em>運動中</em>も同じです。生の <span class="m">Ṙ</span> は二つのことを同時に述べています — 物体の今の姿勢<em>と</em>回る速さ — だからどちらも純粋には述べていません: 同じように回る二つの物体でも、姿勢が違うだけで <span class="m">Ṙ</span> は違います。<span class="m">R<sup>⊤</sup></span> を掛けましょう。これは<button class="termbtn" id="so3gDroneInfo" type="button" aria-expanded="false" aria-controls="so3gDroneNote">運動を単位元へ引き戻します</button> — 姿勢がもう寄与しない場所へ。どちら側から掛けるかが、やはり二つのフレームです:</p><p class="matline"><span class="m">Ω<sub>body</sub> = R<sup>⊤</sup> Ṙ</span></p><p class="matline"><span class="m">Ω<sub>world</sub> = Ṙ R<sup>⊤</sup></span></p><p>ドローンで言えば: <span class="m">Ω<sub>body</sub></span> は<em>パイロットの指令</em>です — 「自分の軸まわりに、この速さで回れ」 — 指令が続くかぎり一定です。<span class="m">Ṙ</span> は<em>地上のレーダーが見るもの</em>です: 同じ一定の指令が、機体が向きを変えるにつれて絶えず<em>変化する</em> <span class="m">Ṙ</span> を生みます。だからジャイロの測定値をそのままワールドフレームで積分してはいけません — ジャイロは <span class="m">body</span> で測っているからです。</p><div class="bubble" id="so3gDroneNote" role="dialog" aria-label="引き戻しと随伴" hidden><p>二つのフレームは同じ運動を別の帳簿で書いたもので、一方から他方へは<em>随伴</em>で移れます:</p><p class="matline"><span class="m">Ω<sub>world</sub> = R Ω<sub>body</sub> R<sup>⊤</sup></span></p><p class="matline"><span class="m">ω<sub>world</sub> = R ω<sub>body</sub></span></p><p>前者は行列形、後者は <span class="m">ℝ<sup>3</sup></span> の軸ベクトルに対する同じ主張です。これは存在しうる最も単純な随伴です: <span class="m">Ad<sub>R</sub> = R</span>。<span class="m">SE(3)</span> ではこれが <span class="m">6×6</span> になり、回転部分と並進部分を混ぜます — そこでは専用の駅が与えられています。</p><p>形に注目してください: 上の左右の摂動と同じ「同じ運動を別の視点から」という形です。<span class="m">Ṙ</span> は間違いではありません — ただ、それ自体が動いている基底で書かれているだけです。</p></div><p>ただし<button class="termbtn" id="so3gCommInfo" type="button" aria-expanded="false" aria-controls="so3gCommNote">小さな角ではほとんど見えません</button> — だからこそ誤った Jacobian が何週間も生き延びるのです。</p><div class="bubble" id="so3gCommNote" role="dialog" aria-label="なぜ小さな角では見えないのか" hidden><p>Baker–Campbell–Hausdorff の公式の最初の二項:</p><p class="matline"><span class="m">exp(ω<sub>1</sub>) exp(ω<sub>2</sub>) = exp(ω<sub>1</sub> + ω<sub>2</sub> + ½[ω<sub>1</sub>, ω<sub>2</sub>] + …)</span></p><p><span class="m">SO(3)</span> では交換子はちょうど外積です: <span class="m">[ω<sub>1</sub>, ω<sub>2</sub>] = ω<sub>1</sub> × ω<sub>2</sub></span>。</p><p>つまり誤差項は角の大きさについて<strong>二次</strong>です。<span class="m">‖ω‖ ~ 10<sup>−3</sup></span> なら順序の入れ替えの代償は <span class="m">~10<sup>−6</sup></span> — 測定ノイズの下です。</p><p>これは主題全体を貫く模様です: <em>小さな角では見えず、大きな角で突然効く</em>。誤った版も収束はします、ただ悪く収束するだけ — だからテストを通ってしまい、だからループ閉じ込みで噛みつくのです。</p></div>'},
        {t:'ジンバルロック: 自由度が一つ消える', b:'<p>Euler 角は三つの回転を入れ子にします — シーンの三つの環です。外側は <span class="m">α</span> だけ、真ん中は <span class="m">β</span> だけ、内側は <span class="m">γ</span> だけ回ります。真ん中が 90° に近づくとどうなるか見てください: 内側の環の軸が外側の軸に<strong>重なっていきます</strong>。二つの軸の内積はちょうど <span class="m">sin β</span> であり、90° では 1 — そこでは二つのダイヤルが同じ回転をしています。ダイヤルは三つ、独立な向きは二つ: 自由度が一つ消え、<span class="m">(α, β, γ) ↦ R</span> という写像の微分が階数を落とします。</p><p>しかも迂回できる一点ではありません。ジンバルロックの<em>近く</em>では、小さな回転にも法外な角速度が要ります。近傍まるごとが悪条件なのです。</p><p>なぜ真ん中の角なのか。外側の二つは、結局<em>内側の軸の向きを指定している</em>だけだからです: <span class="m">α</span> がその経度、<span class="m">β</span> が緯度です。ジンバルロックとは、この球面地図の<strong>極</strong>のことです: そこで子午線が集まり、そこで経度は意味を失い、そこで「経度のダイヤルを回す」ことと「その場で回る」ことが同じ動きになります。平面に広げたどんな世界地図もこの点から逃れられません — 製図者の落ち度ではないのです。</p><p>こうした平らな地図一枚には専門用語もあります: <strong>チャート</strong>（chart）— 曲がった空間の一部分を平坦に座標づけたものです。Euler 角は <span class="m">SO(3)</span> 上の一枚のチャートであり、そのチャートが極で壊れているのです。</p><p>よくある反応は、これは Euler 角の不器用さであって、賢いチャートなら直る、というものです。<strong>直りません</strong> — 続く二つの駅がまさにその話です。<span class="m">SO(3)</span> から始めるのではなく、問いが最も簡単な場所、円から始めます。</p>'},
        {t:'一枚のチャートでは足りない — 円', b:'<p>まだ問うていなかったことから始めましょう: そもそも<em>なぜ</em>平坦な座標が欲しいのか。推定値に対して我々がすることは、すべてベクトル空間の算術だからです: 増分を<em>足し</em>、歩幅で<em>スケール</em>し、二つの推定を<em>平均</em>し、微分する。<span class="m">ℝ<sup>n</sup></span> はそれを無償で与えます — だから平坦な衛星が基準線でした。曲がった空間では、そのどれも成分ごとには働かず、平坦な座標だけがそれらを取り戻してくれるはずのものです。賭けられているのはそれです。</p><p>存在しうる最小の曲がった空間から始めます。<span class="m">SO(2)</span> の衛星で見たとおり、<span class="m">θ</span> と <span class="m">θ + 2π</span> は同じ回転なので、パラメータ空間は一周して戻ります。</p><p class="matline"><span class="m">SO(2) ≅ S<sup>1</sup></span></p><p><span class="m">S<sup>n</sup></span> という記法はこの先ずっと付いてくるので、一度きちんと言っておきます: <span class="m">S<sup>n</sup></span> とは <span class="m">ℝ<sup>n+1</sup></span> の単位球の<em>表面</em>のことです。</p><p class="matline"><span class="m">S<sup>n</sup> = { x ∈ ℝ<sup>n+1</sup> : ‖x‖ = 1 }</span></p><p>つまり <span class="m">S<sup>1</sup></span> は円（自由度 1）、<span class="m">S<sup>2</sup></span> は球の<em>表面</em>（2）、以下同様です。どれも曲がっていて、どれも自分自身へ閉じています。</p><p>円を<em>一枚</em>のチャートで覆おうとしてみましょう。<span class="m">θ ∈ (−π, π)</span> は円のすべての点を指せますが、ただ一点だけ指せません: <span class="m">θ = π</span> の回転です。シーンを見てください。緑の目印が一周し、その <span class="m">θ</span> は隙間のところで <span class="m">+π</span> から <span class="m">−π</span> へ<strong>飛びます</strong>。これが<em>継ぎ目</em>です。切れ目をどこへずらしても、継ぎ目は消えず、移動するだけです。</p><p>そしてこれは不器用さではなく、<button class="termbtn" id="so3gCircInfo" type="button" aria-expanded="false" aria-controls="so3gCircNote">コンパクト性</button>です。空間が<strong>コンパクト</strong>とは、外へ逃がさないということです: もはや空間の一部ではないどこかへ逃げ出す列を含まない、ということです。円はそうです。<em>開</em>区間はそうではありません — 端へ向かう列の極限は外へこぼれます。（<em>開</em>とは自分の境界を含まないこと。座標には、どの点のまわりにも少しの余地が要るからです。）そしてコンパクトな空間と非コンパクトな空間は、両方向に連続な対応で結べません — どんなに工夫しても、円は一枚のチャートでは覆えないのです。</p><p>二枚なら覆えます。シーンでは二本目の青緑の弧が継ぎ目の上に乗り、両側で重なっています。重なりをもつ複数のチャート — これにも名前があります: <strong>アトラス</strong>です。曲がった空間に対する誠実な答えですが、何を諦めたかに注意してください: <em>一つ</em>の平坦な座標ではなく、貼り合わせた複数になったのです。</p><p>二つの空間を見分ける、もう一つの独立した方法があります: <strong>ループを数える</strong>ことです。互いに連続変形で移り合えないループが何種類あるか。円では、何周するかの回数だけ — 巻き付き数、つまり整数です。平坦な空間ではどのループも一点に縮むので、ちょうど一種類。このループの数え上げを <span class="m">π<sub>1</sub></span> と呼びます。</p><p class="matline"><span class="m">π<sub>1</sub>(S<sup>1</sup>) = ℤ</span></p><p class="matline"><span class="m">π<sub>1</sub>(ℝ<sup>n</sup>) = 0</span></p><p><span class="m">π<sub>1</sub></span> が異なる二つの空間は、同じ空間を別に描いたものではありえません。つまり円にはすでに<em>二つ</em>の独立した障害があり、そのどちらも一次元上へ持ち上がります。</p><div class="bubble" id="so3gCircNote" role="dialog" aria-label="コンパクト性を正確に" hidden><p><strong>コンパクト性。</strong>閉かつ有界（Heine–Borel）、同値な言い方では、どの無限列にも空間の<em>内部</em>で収束する部分列がある、ということです。区間 <span class="m">(−π, π)</span> ではこれが破れます: <span class="m">π</span> へ向かう列の極限は、もうその集合に入っていません。</p><p><strong>なぜそれで決着がつくのか。</strong>コンパクト空間の連続像はコンパクトです。もし円と開区間の間に両方向に連続な対応があれば、その区間は円の連続像、したがってコンパクトのはずですが、そうではありません。矛盾です。しかもこの議論は、角度も座標も使っていません。</p></div>'},
        {t:'ジンバルロックは定理であって不便ではない', b:'<p>一段上へ: <span class="m">S<sup>2</sup></span>、球の表面です。緯度と経度はその上の一枚のチャートであり、二つ前の駅で内側の軸の向きを指定したのと同じものです。シーンでは二つの琥珀色の目印が終始<em>同じ</em>経度差を保っていますが、極へ這い上がるにつれて、その間の弧は尽きていきます: 長さは <span class="m">R·Δλ·cos φ</span> であり、死ぬのは <span class="m">cos φ</span> です。環のときと同じ崩れ方です。そして<em>何が</em>救わなかったかにも注意してください: 球面ではどのループも縮み、平坦な空間と同じく <span class="m">π<sub>1</sub>(S<sup>2</sup>) = 0</span> ですが、それでも一枚のチャートでは覆えません。コンパクトだからです。コンパクト性のほうが強く、単独でも効く障害であり、ループはそれとは独立な二つめの障害です。</p><p>そしていよいよ、我々が関心をもつ段です。<span class="m">SO(3)</span> は 3 次元でコンパクトであり、そのループが意外なのです: 360° 回転のループは<strong>縮まず</strong>、720° のループは縮みます。円のように無限個の類があるのではなく、ちょうど<button class="termbtn" id="so3gTopInfo" type="button" aria-expanded="false" aria-controls="so3gTopNote">二つ</button>です。</p><p>これで材料はそろいました。大域的な平坦座標は定義上、<em>微分同相</em>——破ることも貼ることもない、両方向に滑らかな付け替え——を <span class="m">SO(3)</span> と <span class="m">ℝ<sup>3</sup></span> の開集合との間に与えることになります。しかしそうした付け替えは位相不変量をすべて保ち、ここでは二つが独立に壊れます:</p><p class="matline"><span class="m">SO(3) はコンパクト</span></p><p class="matline"><span class="m">ℝ<sup>3</sup> の開集合はそうでない</span></p><p class="matline"><span class="m">π<sub>1</sub>(SO(3)) = ℤ/2</span></p><p class="matline"><span class="m">π<sub>1</sub>(ℝ<sup>3</sup>) = 0</span></p><p class="matline"><span class="m">SO(3) に大域的で特異点のない 3 パラメータ座標は存在しない</span></p><p>コンパクト性だけで十分です——円で最後まで追った、まさにその議論です。そして問題は個数ではありません: <span class="m">SO(3)</span> はちょうど 3 次元なので、三つの数はまさに正しい量です。悪いのは平坦な <span class="m">ℝ<sup>3</sup></span> の<em>形</em>です: どこでも巻き戻らず、どこにも終わりがない。</p><p>定理が言わないのは、<em>何で</em>払うかです。Euler 角は階数の喪失で払います。それがジンバルロックです。Rodrigues ベクトルは継ぎ目で払います——<span class="m">θ = π</span> の球殻では <span class="m">+πa</span> と <span class="m">−πa</span> が同じ回転になります——が、その殻までは微分がフルランクのままです。実務を決めるのはこの違いです: 小さな増分が <span class="m">π</span> の近くまで行くことはありませんが、保存された絶対姿勢はいつでもそこに居うるのです。</p><p>ここまで来ると、逃げ道も読めます。<strong>四元数</strong>は、いま登ってきた梯子の一段上へ行きます: <span class="m">S<sup>3</sup></span>、<span class="m">ℝ<sup>4</sup></span> の単位球の表面です。<span class="m">S<sup>3</sup></span> は 3 次元で滑らかで、継ぎ目も階数の喪失もありません——ただしそれは<em>拘束</em>（<span class="m">‖q‖ = 1</span>）で買ったものであり、ほかの段と同じくコンパクトで曲がっています。つまり<em>平坦</em>ではなく、平坦さこそが我々の目的でした: 足し算、スケール、微分です。<strong>アトラス</strong>——円のときと同じく複数のチャート——は機能しますが、それは「大域的な平坦座標」という望みを達成したのではなく、放棄したということです。</p><p>したがって実務上の答えは、二者択一ではなく分業です。大域性が効くところでは、回転を行列か四元数として<em>冗長に</em>保存します。定理が何も禁じていないところ——局所接空間——では、<em>増分</em>を 3 次元ベクトルとして取り、そこでは足し算が本来のものに戻ります。それが具体的にどう働くか、そして <span class="m">SO(3)</span> の本当の、<span class="m">ℤ/2</span> の形がどう見えるかは、<em>リーマン勾配</em>の衛星が見せてくれます。</p><div class="bubble" id="so3gTopNote" role="dialog" aria-label="ループと微分同相" hidden><p><strong><span class="m">π<sub>1</sub></span>、基本群。</strong>ループを連続変形の違いを除いて分類したもので、その類は<em>群</em>をなします。演算はループのつなぎ合わせです。したがって <span class="m">ℤ/2</span> は <span class="m">1 + 1 = 0</span> を意味します: 縮まないループの<em>二重</em>は縮むのです。ベルトの手品が示すのはこれです——360° ねじったベルトは端を離さずには平らに戻せませんが、720° ねじったものは戻せます。</p><p><strong>微分同相。</strong>滑らかで可逆な対応であって、その<em>逆も滑らか</em>なものです。座標変換とはまさにこれであり、だからこそ「平坦に変換できないのか」という問いは、<span class="m">SO(3)</span> と <span class="m">ℝ<sup>3</sup></span> の開集合との間に微分同相が存在するか、という問いになります。そして位相不変量をすべて保つ以上、食い違う不変量が一つでもあれば否定されます。</p></div>'}
      ]
    }
  };
})();
